package io.ahroni.dailytally;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.provider.MediaStore;import android.print.PrintManager;import android.webkit.*;import android.view.*;import android.widget.*;import androidx.core.content.FileProvider;import java.io.*;
public class MainActivity extends Activity {
 private WebView web;private ValueCallback<Uri[]> files;private Uri cameraUri;private byte[] pendingExport;private static final int PICK=10,SAVE=11;
 private boolean trusted(String value){try{Uri a=Uri.parse(BuildConfig.APP_URL),b=Uri.parse(value);return "https".equals(b.getScheme())&&a.getHost().equals(b.getHost())&&(b.getPort()==-1||b.getPort()==443);}catch(Exception e){return false;}}
 private void external(String url){try{Uri uri=Uri.parse(url);String s=uri.getScheme();if("https".equals(s)||"mailto".equals(s)||"tel".equals(s))startActivity(new Intent(Intent.ACTION_VIEW,uri));}catch(Exception ignored){Toast.makeText(this,"No app is available to open this link.",Toast.LENGTH_SHORT).show();}}
 @Override public void onCreate(Bundle state){super.onCreate(state);web=new WebView(this);setContentView(web);web.setOnApplyWindowInsetsListener((view,insets)->{view.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});web.requestApplyInsets();WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(true);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);web.addJavascriptInterface(new Exports(),"DailyTallyFiles");
 web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){String url=request.getUrl().toString();if(trusted(url))return false;external(url);return true;}@Override public void onReceivedError(WebView view,WebResourceRequest request,WebResourceError error){if(request.isForMainFrame())new AlertDialog.Builder(MainActivity.this).setTitle("Unable to connect").setMessage("Check your internet connection. The server may take a little time to start.").setPositiveButton("Retry",(d,w)->web.loadUrl(BuildConfig.APP_URL)).setNegativeButton("Close",(d,w)->finish()).show();}@Override public void onPageFinished(WebView view,String url){CookieManager.getInstance().flush();if(!trusted(url))return;view.evaluateJavascript("(()=>{if(window.__dailyNative)return;window.__dailyNative=true;window.print=()=>DailyTallyFiles.printPage();document.addEventListener('click',e=>{const a=e.target.closest('a[download]');if(!a||!a.href.startsWith('blob:'))return;e.preventDefault();fetch(a.href).then(r=>r.blob()).then(blob=>{const reader=new FileReader();reader.onload=()=>DailyTallyFiles.saveFile(a.download||'DailyTally-report.csv',blob.type||'text/plain',reader.result.split(',')[1]);reader.readAsDataURL(blob)}).catch(()=>alert('Unable to save the file. Try again.'))},true)})()",null);}});
 web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView view,ValueCallback<Uri[]> callback,FileChooserParams params){if(files!=null)files.onReceiveValue(null);files=callback;cameraUri=null;Intent content=params.createIntent();content.addCategory(Intent.CATEGORY_OPENABLE);Intent chooser=Intent.createChooser(content,"Choose a photo or file");try{File folder=new File(getCacheDir(),"capture");folder.mkdirs();File file=File.createTempFile("photo-",".jpg",folder);cameraUri=FileProvider.getUriForFile(MainActivity.this,getPackageName()+".files",file);Intent camera=new Intent(MediaStore.ACTION_IMAGE_CAPTURE);camera.putExtra(MediaStore.EXTRA_OUTPUT,cameraUri);camera.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);chooser.putExtra(Intent.EXTRA_INITIAL_INTENTS,new Intent[]{camera});}catch(Exception ignored){}try{startActivityForResult(chooser,PICK);}catch(Exception e){files.onReceiveValue(null);files=null;}return true;}});
 if(state==null)web.loadUrl(BuildConfig.APP_URL);else web.restoreState(state);
 }
 public class Exports {@JavascriptInterface public void printPage(){runOnUiThread(()->{if(!trusted(web.getUrl()))return;PrintManager manager=(PrintManager)getSystemService(PRINT_SERVICE);manager.print("DailyTally report",web.createPrintDocumentAdapter("DailyTally"),null);});}@JavascriptInterface public void saveFile(String filename,String mime,String encoded){if(encoded==null||encoded.length()>30000000)return;runOnUiThread(()->{if(!trusted(web.getUrl())||pendingExport!=null)return;try{pendingExport=android.util.Base64.decode(encoded,android.util.Base64.DEFAULT);String name=new File(filename).getName();if(name.length()>100)name="DailyTally-export.txt";Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType(mime.startsWith("text/")||mime.equals("application/json")?mime:"application/octet-stream");intent.putExtra(Intent.EXTRA_TITLE,name);startActivityForResult(intent,SAVE);}catch(Exception e){pendingExport=null;}});}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==PICK&&files!=null){Uri[] selected=result==RESULT_OK?WebChromeClient.FileChooserParams.parseResult(result,data):null;if(result==RESULT_OK&&(selected==null||selected.length==0)&&cameraUri!=null)selected=new Uri[]{cameraUri};files.onReceiveValue(selected);files=null;cameraUri=null;}if(request==SAVE){try{if(result==RESULT_OK&&data!=null&&pendingExport!=null){try(OutputStream output=getContentResolver().openOutputStream(data.getData())){output.write(pendingExport);}}}catch(Exception e){Toast.makeText(this,"The file could not be saved.",Toast.LENGTH_LONG).show();}finally{pendingExport=null;}}}
 @Override public void onBackPressed(){web.evaluateJavascript("(()=>{const dialog=document.querySelector('dialog[open]');if(dialog){dialog.close();return true}return false})()",result->{if("true".equals(result))return;if(web.canGoBack())web.goBack();else finish();});}
 @Override protected void onSaveInstanceState(Bundle state){web.saveState(state);super.onSaveInstanceState(state);}
}
